parameters.jsCode:
const MAX_IMAGES = 10;

function stripCodeFences(value) {
  return String(value ?? '')
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
}

function extractJsonObject(value) {
  const text = stripCodeFences(value);
  const firstBrace = text.indexOf('{');
  const lastBrace = text.lastIndexOf('}');

  if (firstBrace === -1 || lastBrace === -1 || lastBrace <= firstBrace) {
    return text;
  }

  return text.slice(firstBrace, lastBrace + 1);
}

function escapeRegExp(value) {
  return String(value).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function decodeJsonishString(value) {
  return String(value ?? '')
    .replace(/\\n/g, '\n')
    .replace(/\\r/g, '\r')
    .replace(/\\t/g, '\t')
    .replace(/\\"/g, '"')
    .replace(/\\\//g, '/')
    .replace(/\\\\/g, '\\')
    .trim();
}

function extractStringField(text, fieldName, nextFieldNames = []) {
  const fieldRegex = new RegExp(`"${escapeRegExp(fieldName)}"\\s*:\\s*"`, 'm');
  const match = fieldRegex.exec(text);

  if (!match) return '';

  const valueStart = match.index + match[0].length;
  let valueEnd = -1;

  for (const nextFieldName of nextFieldNames) {
    const nextRegex = new RegExp(`",\\s*"${escapeRegExp(nextFieldName)}"\\s*:`, 'm');
    const searchArea = text.slice(valueStart);
    const nextMatch = nextRegex.exec(searchArea);

    if (nextMatch) {
      const possibleEnd = valueStart + nextMatch.index;
      if (valueEnd === -1 || possibleEnd < valueEnd) {
        valueEnd = possibleEnd;
      }
    }
  }

  if (valueEnd === -1) {
    const tail = text.slice(valueStart);
    const lastQuoteBeforeEnd = tail.lastIndexOf('"');
    if (lastQuoteBeforeEnd === -1) return '';
    valueEnd = valueStart + lastQuoteBeforeEnd;
  }

  return decodeJsonishString(text.slice(valueStart, valueEnd));
}

function extractNumberField(text, fieldName, fallback = 0) {
  const regex = new RegExp(`"${escapeRegExp(fieldName)}"\\s*:\\s*([0-9]+(?:\\.[0-9]+)?)`, 'm');
  const match = regex.exec(text);

  if (!match) return fallback;

  const number = Number(match[1]);
  return Number.isFinite(number) ? number : fallback;
}

function extractArrayText(text, fieldName) {
  const fieldRegex = new RegExp(`"${escapeRegExp(fieldName)}"\\s*:`, 'm');
  const fieldMatch = fieldRegex.exec(text);

  if (!fieldMatch) return '';

  const startSearch = fieldMatch.index + fieldMatch[0].length;
  const start = text.indexOf('[', startSearch);

  if (start === -1) return '';

  let depth = 0;
  let inString = false;
  let escaped = false;

  for (let i = start; i < text.length; i++) {
    const char = text[i];

    if (inString) {
      if (escaped) {
        escaped = false;
      } else if (char === '\\') {
        escaped = true;
      } else if (char === '"') {
        inString = false;
      }
      continue;
    }

    if (char === '"') {
      inString = true;
      continue;
    }

    if (char === '[') {
      depth += 1;
      continue;
    }

    if (char === ']') {
      depth -= 1;

      if (depth === 0) {
        return text.slice(start, i + 1);
      }
    }
  }

  return '';
}

function parseArrayField(text, fieldName) {
  const arrayText = extractArrayText(text, fieldName);

  if (!arrayText) return [];

  try {
    return JSON.parse(arrayText);
  } catch (error) {
    return [];
  }
}

function recoverArticleFromInvalidJson(text) {
  const jsonText = extractJsonObject(text);

  const article = {
    title: extractStringField(jsonText, 'title', ['excerpt']) || 'Untitled Article',
    excerpt: extractStringField(jsonText, 'excerpt', ['contentHtml']) || '',
    contentHtml: extractStringField(jsonText, 'contentHtml', [
      'contentMarkdown',
      'metaTitle',
      'metaDescription',
      'slug',
      'wordCount',
      'seoScore',
      'references',
      'imagePrompts',
      'imagePrompt'
    ]),
    contentMarkdown: extractStringField(jsonText, 'contentMarkdown', [
      'metaTitle',
      'metaDescription',
      'slug',
      'wordCount',
      'seoScore',
      'references',
      'imagePrompts',
      'imagePrompt'
    ]),
    metaTitle: extractStringField(jsonText, 'metaTitle', ['metaDescription']) || '',
    metaDescription: extractStringField(jsonText, 'metaDescription', ['slug']) || '',
    slug: extractStringField(jsonText, 'slug', ['wordCount']) || '',
    wordCount: extractNumberField(jsonText, 'wordCount', 0),
    seoScore: extractNumberField(jsonText, 'seoScore', 0),
    references: parseArrayField(jsonText, 'references'),
    imagePrompts: parseArrayField(jsonText, 'imagePrompts'),
    imagePrompt: ''
  };

  article.imagePrompt =
    extractStringField(jsonText, 'imagePrompt', []) ||
    article.imagePrompts?.[0]?.prompt ||
    '';

  if (!article.contentHtml) {
    throw new Error('Could not recover contentHtml from invalid AI JSON');
  }

  return article;
}

function parseArticle(raw) {
  if (raw && typeof raw === 'object' && raw.output !== undefined) {
    raw = raw.output;
  }

  if (typeof raw === 'string') {
    const cleaned = extractJsonObject(raw);

    try {
      return JSON.parse(cleaned);
    } catch (error) {
      return recoverArticleFromInvalidJson(cleaned);
    }
  }

  if (raw && typeof raw === 'object') {
    return raw;
  }

  throw new Error('AI article output is empty or unsupported');
}

function getRequestedImageCount() {
  const body = $('Webhook').first().json.body || {};
  const visual = body.visualEngine || {};
  const count = Number(visual.contentImageCount ?? 0);

  const imagesEnabled =
    visual.generateContentImages === true ||
    visual.generateCoverImage === true ||
    count > 0;

  if (!imagesEnabled || !Number.isFinite(count) || count <= 0) return 0;

  return Math.min(Math.floor(count), MAX_IMAGES);
}

function defaultNegativePrompt() {
  return [
    'blurry',
    'low quality',
    'distorted hands',
    'distorted faces',
    'extra fingers',
    'watermark',
    'logo',
    'random text',
    'text artifacts',
    'irrelevant objects',
    'overcrowded composition',
    'unprofessional stock photo look',
    'misleading visuals'
  ].join(', ');
}

function escapeText(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}

function makeSlot(index) {
  return `[[IMAGE_SLOT_${index}]]`;
}

function fallbackPrompt(article, index, total) {
  const body = $('Webhook').first().json.body || {};
  const visual = body.visualEngine || {};
  const client = body.clientProfile || {};

  const style = visual.advanced?.style || 'photoreal';
  const aspectRatio = visual.advanced?.aspectRatio || '16:9';
  const topic = body.contentBrief?.topic || article.title || 'blog article';
  const audience =
    client.targetAudience ||
    body.configuration?.intendedAudience ||
    'general readers';

  const brandColors = Array.isArray(client.brandColors)
    ? client.brandColors.join(', ')
    : '';

  const imageRole =
    index === 1 && visual.generateCoverImage
      ? 'hero featured blog image'
      : `supporting section image ${index} of ${total}`;

  return [
    `Create a professional ${style} ${aspectRatio} ${imageRole} for an article about "${topic}".`,
    `Target audience: ${audience}.`,
    brandColors ? `Subtly fit this brand color palette: ${brandColors}.` : '',
    'Make the image publication-ready, clean, useful, visually distinct, and relevant to the nearby article section.',
    'Use strong lighting, clear composition, realistic details, and no readable text inside the image.'
  ]
    .filter(Boolean)
    .join(' ');
}

function convertOldSlotsToNew(html) {
  return String(html || '').replace(/\{\{IMAGE_SLOT_(\d+)\}\}/g, (_, num) => {
    return makeSlot(Number(num));
  });
}

function removeDuplicateOrOverflowSlots(contentHtml, requestedCount) {
  let html = String(contentHtml || '');
  const seen = new Set();

  html = html.replace(/\[\[IMAGE_SLOT_(\d+)\]\]/g, (match, num) => {
    const n = Number(num);

    if (!Number.isInteger(n) || n < 1 || n > requestedCount) return '';
    if (seen.has(n)) return '';

    seen.add(n);
    return makeSlot(n);
  });

  return html;
}

function insertSlotBeforeHeading(html, slot, headingIndex) {
  const headingRegex = /<h2\b[^>]*>/gi;
  const matches = [...String(html).matchAll(headingRegex)];

  if (matches[headingIndex]) {
    const position = matches[headingIndex].index;
    return html.slice(0, position) + slot + html.slice(position);
  }

  return null;
}

function insertSlotBeforeConclusion(html, slot) {
  const conclusionRegex =
    /<h2\b[^>]*>\s*(conclusion|final thoughts|final takeaway|wrapping up|summary)\s*<\/h2>/i;

  const match = String(html).match(conclusionRegex);

  if (match && match.index !== undefined) {
    return html.slice(0, match.index) + slot + html.slice(match.index);
  }

  return null;
}

function insertSlotBeforeArticleEnd(html, slot) {
  if (String(html).includes('</article>')) {
    return String(html).replace('</article>', `${slot}</article>`);
  }

  return String(html) + slot;
}

function normalizeSlotsInHtml(contentHtml, requestedCount) {
  let html = String(contentHtml || '');

  html = convertOldSlotsToNew(html);

  const emptyImgRegex = /<img\b[^>]*src=(["'])\s*\1[^>]*\/?>/gi;
  let emptyImgIndex = 0;

  html = html.replace(emptyImgRegex, () => {
    emptyImgIndex += 1;
    return emptyImgIndex <= requestedCount ? makeSlot(emptyImgIndex) : '';
  });

  html = removeDuplicateOrOverflowSlots(html, requestedCount);

  for (let i = 1; i <= requestedCount; i++) {
    const slot = makeSlot(i);

    if (html.includes(slot)) continue;

    let updatedHtml = null;

    if (i === 1) {
      updatedHtml = insertSlotBeforeHeading(html, slot, 0);
    } else {
      updatedHtml = insertSlotBeforeHeading(html, slot, i - 1);
    }

    if (!updatedHtml) {
      updatedHtml = insertSlotBeforeConclusion(html, slot);
    }

    if (!updatedHtml) {
      updatedHtml = insertSlotBeforeArticleEnd(html, slot);
    }

    html = updatedHtml;
  }

  return html;
}

function normalizeImagePromptString(value) {
  if (!value) return '';

  if (typeof value === 'string') {
    const cleaned = escapeText(value);

    if (cleaned.startsWith('{') && cleaned.endsWith('}')) {
      try {
        const parsed = JSON.parse(cleaned);
        return escapeText(parsed.prompt);
      } catch (error) {
        return cleaned;
      }
    }

    return cleaned;
  }

  if (typeof value === 'object') {
    return escapeText(value.prompt);
  }

  return escapeText(value);
}

const requestedCount = getRequestedImageCount();
const output = [];

for (const item of $input.all()) {
  const article = parseArticle(item.json);

  if (!article || typeof article !== 'object') {
    throw new Error('Parsed article must be an object');
  }

  if (!article.contentHtml) {
    throw new Error('Article JSON must include contentHtml');
  }

  if (requestedCount === 0) {
    article.imagePrompts = [];
    article.imagePrompt = '';

    output.push({
      json: {
        article,
        generatedImages: [],
        shouldGenerateImages: false
      }
    });

    continue;
  }

  article.contentHtml = normalizeSlotsInHtml(article.contentHtml, requestedCount);

  const originalPrompts = Array.isArray(article.imagePrompts)
    ? article.imagePrompts
    : [];

  const normalizedPrompts = [];

  for (let i = 1; i <= requestedCount; i++) {
    const slot = makeSlot(i);

    const promptItem =
      originalPrompts.find((p) => p?.slot === slot) ||
      originalPrompts.find((p) =>
        String(p?.slot || '').includes(`IMAGE_SLOT_${i}`)
      ) ||
      originalPrompts[i - 1] ||
      {};

    const prompt =
      escapeText(promptItem.prompt) || fallbackPrompt(article, i, requestedCount);

    const alt =
      escapeText(promptItem.alt) || `${article.title || 'Article'} image ${i}`;

    const title =
      escapeText(promptItem.title) || `${article.title || 'Article'} image ${i}`;

    const caption = escapeText(promptItem.caption) || '';

    const normalized = {
      slot,
      placement: escapeText(promptItem.placement) || '',
      sectionHeading: escapeText(promptItem.sectionHeading) || '',
      imageType:
        escapeText(promptItem.imageType) ||
        (i === 1 ? 'featured image' : 'section image'),
      imagePurpose: escapeText(promptItem.imagePurpose) || '',
      prompt,
      negativePrompt:
        escapeText(promptItem.negativePrompt) || defaultNegativePrompt(),
      alt,
      title,
      caption
    };

    normalizedPrompts.push(normalized);

    output.push({
      json: {
        article,
        shouldGenerateImages: true,
        imageIndex: i,
        totalImages: requestedCount,
        slot,
        prompt: `${prompt}\n\nNegative prompt: ${normalized.negativePrompt}`,
        alt,
        title,
        caption,
        placement: normalized.placement,
        sectionHeading: normalized.sectionHeading,
        imageType: normalized.imageType,
        imagePurpose: normalized.imagePurpose,
        model: 'google/gemini-2.5-flash-image'
      }
    });
  }

  article.imagePrompts = normalizedPrompts;
  article.imagePrompt =
    normalizedPrompts[0]?.prompt || normalizeImagePromptString(article.imagePrompt);
}

return output.map((item) => {
  if (!item || typeof item !== 'object') {
    return { json: { value: item } };
  }

  if (!item.json) {
    return { json: item };
  }

  return item;
});

function escapeHtml(value) {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('"', '&quot;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;');
}

function extractImageUrl(response) {
  const message = response.choices?.[0]?.message;

  const direct =
    message?.images?.[0]?.image_url?.url ||
    message?.content?.[0]?.image_url?.url ||
    response.data?.[0]?.url ||
    response.data?.[0]?.b64_json ||
    response.imageUrl ||
    response.image_url ||
    response.url ||
    '';

  if (direct) return String(direct);

  if (typeof message?.content === 'string') {
    const dataUrlMatch = message.content.match(/data:image\/[a-zA-Z0-9.+-]+;base64,[A-Za-z0-9+/=]+/);
    if (dataUrlMatch) return dataUrlMatch[0];

    const httpUrlMatch = message.content.match(/https?:\/\/[^\s"'<>]+/);
    if (httpUrlMatch) return httpUrlMatch[0];
  }

  return '';
}

const sourceItems = $items('Prepare Image Jobs');
const generatedImages = [];

for (let i = 0; i < $input.all().length; i++) {
  const response = $input.all()[i].json;
  const original = sourceItems[i]?.json;

  if (!original) {
    throw new Error(`Missing original image job for generated image index ${i}`);
  }

  let imageUrl = extractImageUrl(response);

  if (
    imageUrl &&
    !imageUrl.startsWith('data:image') &&
    !imageUrl.startsWith('http')
  ) {
    imageUrl = `data:image/png;base64,${imageUrl}`;
  }

  if (!imageUrl) {
    throw new Error(`No generated image URL/base64 returned for ${original.slot}`);
  }

  generatedImages.push({
    imageIndex: original.imageIndex,
    slot: original.slot,
    imageUrl,
    alt: original.alt ?? '',
    title: original.title ?? '',
    caption: '',
    imageHtml: `
<figure class="article-image" data-image-slot="${escapeHtml(original.slot)}">
  <img src="${imageUrl}" alt="${escapeHtml(original.alt ?? '')}" title="${escapeHtml(original.title ?? '')}" loading="lazy" />
</figure>`.trim(),
    article: original.article,
  });
}

generatedImages.sort((a, b) => Number(a.imageIndex) - Number(b.imageIndex));

return [
  {
    json: {
      article: generatedImages[0]?.article,
      generatedImages,
    },
  },
];

const item = $input.first().json;
const article = item.article;

if (!article || typeof article !== 'object') {
  throw new Error('Missing article object before image insertion');
}

const generatedImages = Array.isArray(item.generatedImages)
  ? item.generatedImages
  : [];

let contentHtml = String(article.contentHtml || '');

for (const image of generatedImages) {
  if (!image.slot || !image.imageHtml) continue;

  if (contentHtml.includes(image.slot)) {
    contentHtml = contentHtml.split(image.slot).join(image.imageHtml);
  } else if (contentHtml.includes('</article>')) {
    // Fallback: if the model forgot the slot, still place the image safely before the article closes.
    contentHtml = contentHtml.replace('</article>', `${image.imageHtml}</article>`);
  } else {
    contentHtml += image.imageHtml;
  }
}

// Remove any leftover placeholders so the final article renders cleanly.
contentHtml = contentHtml.replace(/\{\{IMAGE_SLOT_\d+\}\}/g, '');

article.contentHtml = contentHtml;

article.generatedImages = generatedImages.map(img => ({
  slot: img.slot,
  imageUrl: img.imageUrl,
  alt: img.alt,
  title: img.title,
  caption: img.caption,
}));

return [
  {
    json: article,
  },
];

const item = $input.first().json;
return [
  {
    json: item.article || item,
  },
];

