// ── Explode Topics & Build Full Article Request Body ──
// Constructs the EXACT same request shape the Article Generation
// webhook expects, so the bulk flow produces identical output.

const incoming = $json.body ?? $json;
const globalSettings = incoming.globalSettings ?? {};
const topics = Array.isArray(incoming.topics) ? incoming.topics : [];
const batchId = incoming.meta?.batchId ?? incoming.batchId ?? null;
const clientProfile = incoming.clientProfile ?? {};
const internalLinks = incoming.internal_links ?? [];

if (!topics.length) {
  throw new Error('No topics provided in bulk payload');
}

return topics.map((topic, index) => {
  const s = { ...globalSettings, ...(topic.customSettings ?? {}) };

  return {
    json: {
      // ── Meta (kept for callback) ──
      userId: incoming.userId,
      batchId: topic.batchId ?? batchId,
      batchName: incoming.batchName,
      articleId: topic.articleId,
      articleIndex: topic.articleIndex ?? index + 1,
      topicId: topic.id,
      topic: topic.topic,
      targetKeyword: s.targetKeyword ?? '',

      // ── Full request body identical to Article webhook ──
      requestBody: {
        contentBrief: {
          topic: topic.topic || '',
          targetKeyword: s.targetKeyword || '',
          customOutline: s.customOutline || '',
          liveWebResearch: s.liveWebResearch === true || s.liveWebResearch === 'true'
        },
        clientProfile: topic.clientProfile ?? clientProfile,
        structuralElements: {
          geoOptimization: s.geoOptimization === true || s.geoOptimization === 'true',
          hook: s.hook === true,
          faqs: s.faqs === true,
          tables: s.tables === true,
          aiSearchOptimization: s.aiSearchOptimization === true,
          expertInsights: s.expertInsights === true,
          recommendations: s.recommendations === true
        },
        configuration: {
          articleType: s.articleType || 'informational',
          tone: s.tone || 'professional',
          language: s.language || 'english',
          wordCount: Number(s.wordCount) || 1500,
          intendedAudience: s.intendedAudience || '',
          additionalContext: s.additionalContext || '',
          internalLinks: s.internalLinks === true,
          references: s.references === true,
          readabilityLevel: s.readabilityLevel || 'default-7th',
          firstPerson: s.firstPerson === true,
          brandVoiceKnowledge: s.brandVoiceKnowledge === true,
          competitorAnalysis: s.competitorAnalysis === true,
          geoOptimization: s.geoOptimization === true || s.geoOptimization === 'true'
        },
        visualEngine: {
          generateCoverImage: s.generateCoverImage === true,
          generateContentImages: s.generateContentImages === true,
          contentImageCount: Number(s.contentImageCount) || 0,
          advanced: {
            style: s.imageStyle || 'photoreal',
            aspectRatio: s.imageAspectRatio || '16:9'
          }
        },
        internal_links: topic.internal_links ?? internalLinks
      }
    }
  };
});

// ── Build Callback Payload from Article Webhook Response ──
// The article webhook returns the full article JSON (same as single-article flow).
// Extract what the save endpoint needs.

const meta = $('Explode Topics1').first().json;
const response = $input.first().json;

// The response could be the article object directly,
// or wrapped in an array (respondWith: allIncomingItems)
const article = Array.isArray(response) ? response[0] : response;

if (!article || !article.contentHtml) {
  return [{
    json: {
      articleId: meta.articleId,
      batchId: meta.batchId,
      batchName: meta.batchName,
      articleIndex: meta.articleIndex,
      userId: meta.userId,
      topic: meta.topic,
      targetKeyword: meta.targetKeyword,
      status: 'failed',
      error: 'Article webhook returned no contentHtml'
    }
  }];
}

return [{
  json: {
    articleId: meta.articleId,
    batchId: meta.batchId,
    batchName: meta.batchName,
    articleIndex: meta.articleIndex,
    userId: meta.userId,
    topic: meta.topic,
    targetKeyword: meta.targetKeyword,
    title: article.title || '',
    excerpt: article.excerpt || '',
    contentHtml: article.contentHtml || '',
    contentMarkdown: article.contentMarkdown || '',
    metaTitle: article.metaTitle || '',
    metaDescription: article.metaDescription || '',
    slug: article.slug || '',
    wordCount: article.wordCount || 0,
    seoScore: article.seoScore || 0,
    references: article.references || [],
    imagePrompts: article.imagePrompts || [],
    imagePrompt: article.imagePrompt || '',
    generatedImages: article.generatedImages || [],
    model: 'anthropic/claude-opus-4.6',
    status: 'completed'
  }
}];
